# -*- coding: utf-8 -*-
"""أدوات مبتكرة جديدة (6): كشف شذوذ المصروفات، ربحية العملاء، شروط الدفع، أثر رفع السعر، سيناريوهات السيولة، ربحية المنتج الحقيقية."""
from biz_tools import F, S, add, CATS, T
PD = "const sum=a=>a.reduce((s,x)=>s+x,0);const pct=(a,b)=>b?a/b*100:0;const med=a=>{const s=a.slice().sort((x,y)=>x-y),n=s.length;return n?(n%2?s[(n-1)/2]:(s[n/2-1]+s[n/2])/2):0};const dt=s=>{s=String(s).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).trim();let m;if(m=s.match(/^(\\d{1,2})[-\\/.](\\d{1,2})[-\\/.](\\d{4})$/)){const a=+m[1],b=+m[2];return a>12?new Date(+m[3],b-1,a):new Date(+m[3],b-1,a)}const d=new Date(s);return isNaN(d)?null:d};"

add('expense-anomaly-detector', 'finance', '🕵️', 'كاشف شذوذ المصروفات والاحتيال المحتمل (فحص جنائي)',
    'ارفع قائمة المصروفات ليفحصها بسبع قواعد رقابية: قيم شاذة داخل الفئة، مبالغ قريبة من حد الاعتماد، تقسيم فواتير، تكرار، مبالغ مستديرة، عمليات في عطلة نهاية الأسبوع، واختبار بنفورد للأرقام. يعطيك درجة خطورة لكل بند وقائمة مراجعة.',
    [F('d', 'المصروفات (تاريخ | فئة | مورد | مبلغ | وصف)', 'textarea',
       '2026-10-01 | صيانة | شركة النور | 1850 | صيانة مكيفات\n2026-10-03 | صيانة | شركة النور | 1920 | صيانة مكيفات\n2026-10-05 | ضيافة | بقالة الحي | 640 | ضيافة اجتماع\n2026-10-07 | ضيافة | بقالة الحي | 710 | ضيافة\n2026-10-08 | مشتريات مكتبية | مكتبة الرياض | 4900 | أدوات مكتبية\n2026-10-08 | مشتريات مكتبية | مكتبة الرياض | 4850 | أدوات مكتبية\n2026-10-10 | استشارات | مكتب خبرة | 15000 | استشارة\n2026-10-12 | ضيافة | مطعم الشرق | 9800 | وليمة\n2026-10-15 | صيانة | شركة النور | 2010 | صيانة\n2026-10-16 | سفر | وكالة السفر | 3000 | تذاكر\n2026-10-17 | سفر | وكالة السفر | 2750 | تذاكر\n2026-10-20 | ضيافة | بقالة الحي | 690 | ضيافة\n2026-10-22 | مشتريات مكتبية | مكتبة الرياض | 4950 | أدوات\n2026-10-25 | استشارات | مكتب خبرة | 15000 | استشارة', r=9),
     F('lim', 'حد الاعتماد (فوقه يلزم اعتماد أعلى)', 'n', 5000), F('z', 'حساسية القيم الشاذة (أقل = أكثر تنبيهًا)', 'n', 3),
     S('wk', 'عطلة نهاية الأسبوع', [('56', 'الجمعة والسبت'), ('06', 'السبت والأحد'), ('0', 'بدون فحص')])],
    r'''function compute(v){''' + PD + r'''
const R=lines(v.d).map((x,i)=>({i:i,d:x[0]||'',c:x[1]||'-',s:x[2]||'-',a:Math.abs(num(x[3])),n:x[4]||'',fl:[],sc:0})).filter(x=>x.a>0);
if(R.length<3)return'<b>أدخل 3 مصروفات على الأقل.</b>';
const add=(x,t,w)=>{x.fl.push(t);x.sc+=w};
const lim=v.lim,wk=String(v.wk).split('').map(Number),useW=v.wk!=='0';
// 1) قيم شاذة داخل الفئة (MAD)
const cat={};R.forEach(x=>(cat[x.c]=cat[x.c]||[]).push(x));
Object.keys(cat).forEach(k=>{const g=cat[k];if(g.length<4)return;const m=med(g.map(x=>x.a)),mad=med(g.map(x=>Math.abs(x.a-m)));if(!mad)return;g.forEach(x=>{const zz=.6745*(x.a-m)/mad;if(zz>v.z)add(x,'قيمة شاذة في فئة «'+k+'» (أعلى من الوسيط '+f(m,0)+' بكثير)',3)})});
// 2) قرب حد الاعتماد
R.forEach(x=>{if(lim>0&&x.a>=lim*.9&&x.a<lim)add(x,'أقل من حد الاعتماد مباشرة ('+f(x.a/lim*100,0)+'% منه)',2)});
// 3) تقسيم فواتير: نفس المورد ونفس اليوم أو خلال يومين ومجموعها يتجاوز الحد وكل منها دونه
const bySup={};R.forEach(x=>(bySup[x.s]=bySup[x.s]||[]).push(x));
Object.keys(bySup).forEach(k=>{const g=bySup[k].filter(x=>dt(x.d));g.forEach(x=>{const near=g.filter(y=>Math.abs((dt(y.d)-dt(x.d))/864e5)<=2);if(near.length>1&&lim>0&&sum(near.map(y=>y.a))>=lim&&near.every(y=>y.a<lim))add(x,'احتمال تقسيم فاتورة: '+near.length+' عمليات للمورد نفسه خلال يومين مجموعها '+f(sum(near.map(y=>y.a)),0),3)})});
// 4) تكرار نفس المورد والمبلغ
const dk={};R.forEach(x=>{const k=x.s+'|'+x.a;(dk[k]=dk[k]||[]).push(x)});Object.values(dk).forEach(g=>{if(g.length>1)g.forEach(x=>add(x,'تكرار: نفس المورد ونفس المبلغ '+g.length+' مرات',3))});
// 5) مبالغ مستديرة
R.forEach(x=>{if(x.a>=1000&&x.a%500===0)add(x,'مبلغ مستدير تمامًا ('+f(x.a,0)+')',1)});
// 6) نهاية الأسبوع
if(useW)R.forEach(x=>{const d=dt(x.d);if(d&&wk.indexOf(d.getDay())>=0)add(x,'عملية في يوم عطلة',1)});
// 7) بنفورد
const dg={};for(let k=1;k<=9;k++)dg[k]=0;R.forEach(x=>{const m=String(x.a).replace(/[^1-9]/,'').charAt(0);if(m&&m>='1'&&m<='9')dg[m]++});const n=R.length;
const ben=[1,2,3,4,5,6,7,8,9].map(k=>{const e=Math.log10(1+1/k)*n;return{k:k,o:dg[k],e:e,p:pct(dg[k],n),ep:Math.log10(1+1/k)*100}});const chi=sum(ben.map(b=>Math.pow(b.o-b.e,2)/b.e));
const benOK=n>=30,benBad=benOK&&chi>15.51;
const minor=R.filter(x=>x.fl.length&&x.sc<2).length;const F2=R.filter(x=>x.sc>=2).sort((a,b)=>b.sc-a.sc);
const lvl=s=>s>=5?'<b style="color:#c33">🔴 عالٍ</b>':s>=3?'<b style="color:#c80">🟠 متوسط</b>':'<b style="color:#0a7">🟡 منخفض</b>';
const tot=sum(R.map(x=>x.a)),ft=sum(F2.map(x=>x.a));
const cs=Object.keys(cat).map(k=>{const g=cat[k],fg=g.filter(x=>x.fl.length);return[k,g.length,f(sum(g.map(x=>x.a)),0),fg.length,f(pct(fg.length,g.length),0)+'%']}).sort((a,b)=>b[3]-a[3]);
return kpis([kpi('عمليات مفحوصة',R.length),kpi('بنود للمراجعة',F2.length,F2.length?'bad':'good'),kpi('قيمة البنود المعلّمة',f(ft,0),ft?'bad':'good'),kpi('نسبة القيمة المعلّمة',f(pct(ft,tot),0)+'%'),kpi('اختبار بنفورد',benOK?(benBad?'انحراف':'طبيعي'):'يحتاج 30+ عملية',benBad?'bad':'')])
+'<h4>بنود تستحق المراجعة (مرتبة بالخطورة)</h4>'+(F2.length?tbl(['التاريخ','الفئة','المورد','المبلغ','الخطورة','الأسباب'],F2.map(x=>[x.d,x.c,x.s,f(x.a,0),lvl(x.sc),x.fl.join('<br>')])):'<p>لا بنود مشبوهة وفق القواعد الحالية.</p>')
+'<h4>ملخص الفئات</h4>'+tbl(['الفئة','العمليات','القيمة','معلَّمة','نسبة التعليم'],cs)
+(benOK?'<h4>اختبار بنفورد (أول رقم من المبلغ)</h4>'+tbl(['الرقم','العدد الفعلي','المتوقع','النسبة الفعلية','النسبة المتوقعة'],ben.map(b=>[b.k,b.o,f(b.e,1),f(b.p,1)+'%',f(b.ep,1)+'%']))+note((minor?minor+' بند إضافي بإشارة ضعيفة واحدة (مبلغ مستدير/عطلة) لم يُدرج في القائمة. ':'')+'مربع كاي = '+f(chi,1)+' (الحد الحرج 15.5 عند 95%). الانحراف إشارة للفحص وليس دليل احتيال.'):note('اختبار بنفورد يحتاج 30 عملية فأكثر ليكون ذا معنى.'))
+rec([F2.length?'ابدأ بالبنود الحمراء: اطلب الفاتورة الأصلية وأمر الشراء وتأكد من هوية المورد والمستلم.':'القواعد الحالية لم تُظهر مخاطر، جرّب خفض الحساسية.','البنود المكررة والمقسَّمة هي الأكثر ارتباطًا بالاحتيال أو الأخطاء، قارنها بكشف المورد.','القواعد مؤشرات فقط: قد تكون العملية سليمة، والقرار للمراجعة المستندية.','للحماية الدائمة: ضع حدود اعتماد، وافصل مهام الطلب والاعتماد والدفع، وراجع الموردين الجدد.'])
+aiOut('أنت مدقق داخلي. حلّل نتائج فحص المصروفات التالية واقترح إجراءات تحقق وضوابط رقابية: '+JSON.stringify(F2.slice(0,10).map(x=>({d:x.d,c:x.c,s:x.s,a:x.a,why:x.fl}))))}''', True)

add('customer-profitability-analyzer', 'sales', '💎', 'محلل الربحية الحقيقية للعملاء (بعد الخصم والمرتجع وتكلفة الخدمة والتمويل)',
    'العميل الأكبر مبيعًا ليس بالضرورة الأربح. أدخل لكل عميل الإيراد والتكلفة والخصومات والمرتجعات وأيام السداد وساعات الخدمة، لتعرف الربح الحقيقي ومن تنمّي ومن تعيد التفاوض معه.',
    [F('d', 'العملاء (عميل | إيراد | تكلفة مبيعات | خصومات | مرتجعات | أيام السداد | ساعات خدمة)', 'textarea',
       'شركة الأفق | 500000 | 330000 | 40000 | 15000 | 75 | 120\nمؤسسة النخبة | 320000 | 190000 | 8000 | 4000 | 30 | 40\nمتجر الورد | 90000 | 52000 | 2000 | 1000 | 15 | 12\nشركة البناء | 410000 | 300000 | 35000 | 20000 | 90 | 150\nمطاعم الذوق | 150000 | 82000 | 3000 | 2000 | 21 | 25', r=6),
     F('hr', 'تكلفة ساعة الخدمة (دعم/زيارات/إدارة)', 'n', 90), F('k', 'تكلفة التمويل السنوية %', 'n', 12)],
    r'''function compute(v){''' + PD + r'''
const R=lines(v.d).map(x=>({n:x[0],r:num(x[1]),c:num(x[2]),ds:num(x[3]),rt:num(x[4]),dy:num(x[5]),h:num(x[6])})).filter(x=>x.n&&x.r>0);
if(!R.length)return'<b>أدخل عميلًا واحدًا على الأقل.</b>';
R.forEach(x=>{x.net=x.r-x.ds-x.rt;x.gp=x.net-x.c;x.fin=x.net*(v.k/100)*x.dy/365;x.sv=x.h*v.hr;x.tp=x.gp-x.fin-x.sv;x.m=pct(x.tp,x.r);x.gm=pct(x.gp,x.r)});
const T=sum(R.map(x=>x.tp)),Rv=sum(R.map(x=>x.r)),am=pct(T,Rv),mp=med(R.map(x=>x.tp));
R.forEach(x=>{x.k=x.tp<0?'🔴 خاسر — أعد التفاوض أو أوقف':x.m<am*.6?'🟠 ربحية ضعيفة — أصلح السعر/الشروط':x.tp>=mp&&x.m>=am?'🟢 نمِّ — عميل ممتاز':'🔵 حافظ'});
const S=R.slice().sort((a,b)=>b.tp-a.tp);let cum=0;const rows=S.map((x,i)=>{cum+=x.tp;return[i+1,x.n,f(x.r,0),f(x.gm,1)+'%',f(x.fin,0),f(x.sv,0),'<b>'+f(x.tp,0)+'</b>',f(x.m,1)+'%',f(pct(cum,Math.abs(T)||1),0)+'%',x.k]});
const loss=R.filter(x=>x.tp<0),lossV=sum(loss.map(x=>x.tp));
const byRev=R.slice().sort((a,b)=>b.r-a.r)[0],byProf=S[0];
return kpis([kpi('إجمالي الإيراد',f(Rv,0)),kpi('الربح الحقيقي',f(T,0),T>=0?'good':'bad'),kpi('الهامش الحقيقي',f(am,1)+'%'),kpi('عملاء خاسرون',loss.length,loss.length?'bad':'good'),kpi('أثر الخاسرين',f(lossV,0),lossV<0?'bad':'good')])
+'<h4>ترتيب العملاء بالربح الحقيقي</h4>'+tbl(['#','العميل','الإيراد','هامش إجمالي','تكلفة تمويل التأخير','تكلفة الخدمة','الربح الحقيقي','هامش حقيقي','تراكمي','التوصية'],rows)
+rec([byRev.n!==byProf.n?'أكبر عميل إيرادًا ('+byRev.n+') ليس الأربح؛ الأربح هو '+byProf.n+'.':'أكبر عميل إيرادًا هو أيضًا الأربح: '+byProf.n+'.',loss.length?'العملاء الخاسرون ('+loss.map(x=>x.n).join('، ')+') يهدرون '+f(-lossV,0)+'؛ عدّل الأسعار أو قلّل الخصومات أو قصّر مدة السداد.':'لا يوجد عميل خاسر.','قلّل الخصومات للعملاء ذوي الربحية الضعيفة تدريجيًا بدل إيقافهم مباشرة.','اربط الخصم بسرعة السداد: كل 10 أيام تأخير تكلّف نحو '+f(v.k/365*10,2)+'% من المبيعات.'])
+aiOut('أنت مستشار مبيعات. اقترح خطة لكل شريحة عملاء (نمِّ/حافظ/أصلح/أوقف) استنادًا إلى: '+JSON.stringify(S.map(x=>({n:x.n,profit:Math.round(x.tp),margin:Math.round(x.m)}))))}''', True)

add('payment-terms-optimizer', 'finance', '⏱️', 'محسّن شروط الدفع وخصومات السداد المبكر',
    'هل تستفيد من خصم 2/10 صافي 30؟ يحسب المعدل السنوي الضمني لكل مورد ويقارنه بتكلفة تمويلك، ويرتب الفرص ضمن السيولة المتاحة، ليخبرك أي الفواتير تُدفع مبكرًا وأيها تؤجَّل.',
    [F('d', 'الفواتير (مورد | مبلغ | خصم % | أيام الخصم | أيام الاستحقاق)', 'textarea',
       'مورد أ | 80000 | 2 | 10 | 30\nمورد ب | 45000 | 1 | 10 | 30\nمورد ج | 120000 | 3 | 7 | 45\nمورد د | 30000 | 0.5 | 15 | 30\nمورد هـ | 60000 | 2 | 10 | 60', r=6),
     F('k', 'تكلفة تمويلك السنوية % (قرض/فرصة بديلة)', 'n', 12), F('c', 'السيولة المتاحة الآن (0 = غير محددة)', 'n', 150000)],
    r'''function compute(v){''' + PD + r'''
const R=lines(v.d).map(x=>({n:x[0],a:num(x[1]),d:num(x[2]),dd:num(x[3]),due:num(x[4])})).filter(x=>x.a>0&&x.d>0&&x.due>x.dd);
if(!R.length)return'<b>أدخل فاتورة واحدة على الأقل (أيام الاستحقاق أكبر من أيام الخصم).</b>';
R.forEach(x=>{x.pay=x.a*(1-x.d/100);x.sv=x.a*x.d/100;x.days=x.due-x.dd;x.apr=(x.d/(100-x.d))*(365/x.days)*100;x.fin=x.pay*(v.k/100)*x.days/365;x.net=x.sv-x.fin;x.take=x.apr>v.k});
const S=R.slice().sort((a,b)=>b.apr-a.apr);let cash=v.c>0?v.c:Infinity,tot=0,used=0;
S.forEach(x=>{if(x.take&&x.pay<=cash){x.go=true;cash-=x.pay;used+=x.pay;tot+=x.net}else x.go=false});
const rows=S.map(x=>[x.n,f(x.a,0),f(x.d,1)+'%','خلال '+x.dd+' يوم',f(x.apr,1)+'%',f(x.sv,0),f(x.fin,0),'<b>'+f(x.net,0)+'</b>',x.go?'✅ ادفع مبكرًا':x.take?'⚠️ مجدية لكن السيولة لا تكفي':'⏳ ادفع عند الاستحقاق']);
const best=S[0];
return kpis([kpi('أفضل عائد ضمني',f(best.apr,1)+'%',best.apr>v.k?'good':''),kpi('فواتير مجدية',S.filter(x=>x.take).length+' من '+S.length),kpi('مدفوعات مبكرة مقترحة',f(used,0)),kpi('صافي الوفر السنوي بعد التمويل',f(tot,0),tot>0?'good':'')])
+'<h4>تحليل الفواتير (مرتبة بالعائد)</h4>'+tbl(['المورد','الفاتورة','الخصم','الشرط','العائد السنوي الضمني','وفر الخصم','تكلفة التمويل للفترة','الصافي','القرار'],rows)
+rec(['القاعدة: ادفع مبكرًا إذا كان العائد الضمني أعلى من تكلفة تمويلك '+f(v.k,1)+'%. خصم 2/10 صافي 30 يعادل نحو 37%.','المقارنة بنفس الأساس: العائد يُحسب على الفترة المكتسبة فقط ('+f(best.days,0)+' يومًا للأفضل).','إن كانت السيولة محدودة فالأولوية للعائد الأعلى، ولا تقترض بفائدة أعلى من العائد الضمني.','فاوض الموردين على خصم أعلى للدفع المبكر؛ كل 0.5% إضافية تزيد العائد السنوي بوضوح.'])}''')

add('price-increase-impact', 'sales', '📈', 'محلل أثر رفع الأسعار ونقطة تحمّل فقدان العملاء',
    'كم يمكنك أن تفقد من المبيعات قبل أن يضر رفع السعر بأرباحك؟ يحسب نسبة التحمل والأرباح المتوقعة لعدة نسب رفع بحسب مرونة طلبك، ويقترح خطة رفع مرحلية.',
    [F('p', 'سعر البيع الحالي', 'n', 100), F('c', 'التكلفة المتغيرة للوحدة', 'n', 60), F('q', 'الوحدات المباعة شهريًا', 'n', 1000), F('i', 'نسبة الرفع المخطط %', 'n', 8),
     F('e', 'مرونة الطلب (فقد الحجم % لكل 1% رفع)', 'n', 0.8), F('fx', 'تكاليف ثابتة شهرية (اختياري)', 'n', 0)],
    r'''function compute(v){''' + PD + r'''
const m=v.p-v.c;if(m<=0)return'<b>التكلفة المتغيرة تساوي السعر أو تزيد.</b>';
const base=m*v.q-v.fx,sc=i=>{const dp=v.p*i/100,np=v.p+dp,nm=np-v.c,loss=Math.min(100,v.e*i),nq=v.q*(1-loss/100),pr=nm*nq-v.fx,tol=dp/(m+dp)*100;return{i:i,np:np,nm:nm,loss:loss,nq:nq,pr:pr,tol:tol,d:pr-base}};
const cur=sc(v.i),rows=[2,3,5,8,10,15,20].map(sc).map(x=>[f(x.i,0)+'%',f(x.np,2),f(x.nm/x.np*100,1)+'%','<b>'+f(x.tol,1)+'%</b>',f(x.loss,1)+'%',f(x.nq,0),f(x.pr,0),'<b style="color:'+(x.d>=0?'#0a7':'#c33')+'">'+(x.d>=0?'+':'')+f(x.d,0)+'</b>']);
const best=[1,2,3,4,5,6,8,10,12,15,20,25,30].map(sc).sort((a,b)=>b.pr-a.pr)[0];
const stage=cur.i>6?[Math.round(cur.i/2),cur.i-Math.round(cur.i/2)]:[cur.i];
return kpis([kpi('هامش الوحدة الحالي',f(m,2)),kpi('الربح الشهري الحالي',f(base,0)),kpi('تحمّل فقد المبيعات عند '+f(cur.i,0)+'%',f(cur.tol,1)+'%','good'),kpi('الفقد المتوقع',f(cur.loss,1)+'%',cur.loss>cur.tol?'bad':'good'),kpi('الربح بعد الرفع',f(cur.pr,0),cur.d>=0?'good':'bad')])
+'<h4>مقارنة نسب الرفع</h4>'+tbl(['الرفع','السعر الجديد','هامش %','أقصى فقد تتحمله','الفقد المتوقع','الوحدات المتوقعة','الربح الشهري','الفرق عن الحالي'],rows)
+rec(['عند رفع '+f(cur.i,0)+'% تتحمل خسارة حتى '+f(cur.tol,1)+'% من الحجم؛ المتوقع '+f(cur.loss,1)+'% ('+(cur.loss<=cur.tol?'الرفع مجدٍ':'الرفع يضر بالربح')+').','الرفع الأمثل نظريًا بمرونة '+v.e+' هو نحو '+best.i+'% بربح '+f(best.pr,0)+'. إن لم تكن المرونة معروفة فاختبرها على شريحة صغيرة.',stage.length>1?'نفّذ على مرحلتين: '+stage.map(x=>x+'%').join(' ثم ')+' بينهما 60–90 يومًا وراقب الفقد.':'ارفع دفعة واحدة صغيرة وراقب الفقد 30 يومًا.','ادعم الرفع بقيمة: ميزة جديدة أو باقة أو ضمان، واحمِ العملاء الأوفياء بسعر انتقالي.'])}''')

add('runway-scenario-planner', 'finance', '🛫', 'مخطط سيناريوهات السيولة والمدرج النقدي (متفائل/أساسي/متشائم)',
    'يحاكي رصيدك النقدي شهريًا في ثلاثة سيناريوهات ليخبرك متى ينفد النقد، ومتى تبلغ التعادل، وكم يلزمك من التمويل ومتى تبدأ بطلبه.',
    [F('cash', 'الرصيد النقدي الحالي', 'n', 400000), F('rev', 'الإيراد الشهري الحالي', 'n', 120000), F('g', 'نمو الإيراد الشهري % (أساسي)', 'n', 4),
     F('fx', 'التكاليف الثابتة الشهرية', 'n', 95000), F('vp', 'التكلفة المتغيرة % من الإيراد', 'n', 35), F('cg', 'نمو التكاليف الثابتة شهريًا %', 'n', 1),
     F('dg', 'فارق النمو بين السيناريوهات (نقاط)', 'n', 3), F('h', 'أفق المحاكاة بالأشهر', 'n', 24)],
    r'''function compute(v){''' + PD + r'''
const H=Math.min(60,Math.max(6,Math.round(v.h)));
const run=g=>{let c=v.cash,rv=v.rev,fx=v.fx,out=null,be=null,min=c,rows=[];for(let t=1;t<=H;t++){rv=rv*(1+g/100);fx=fx*(1+v.cg/100);const net=rv-fx-rv*v.vp/100;c+=net;if(be===null&&net>=0)be=t;if(out===null&&c<0)out=t;if(c<min)min=c;rows.push({t:t,rv:rv,net:net,c:c})}return{out:out,be:be,min:min,end:c,rows:rows,g:g}};
const S=[['🟢 متفائل',run(v.g+v.dg)],['🔵 أساسي',run(v.g)],['🔴 متشائم',run(v.g-v.dg)]];
const rows=S.map(([n,s])=>[n,f(s.g,1)+'%',s.out?'<b style="color:#c33">الشهر '+s.out+'</b>':'لا ينفد خلال '+H+' شهرًا',s.be?'الشهر '+s.be:'لا يتحقق',f(s.min,0),f(s.end,0)]);
const bs=S[1][1],ws=S[2][1];const need=Math.max(0,-ws.min);
const mt=bs.rows.filter(r=>r.t%3===0||r.t===1).map(r=>[r.t,f(r.rv,0),f(r.net,0),f(r.c,0)]);
const mw=ws.out?Math.max(0,ws.out-6):null;
return kpis([kpi('الرصيد الحالي',f(v.cash,0)),kpi('نفاد النقد (أساسي)',bs.out?'الشهر '+bs.out:'لا ينفد',bs.out?'bad':'good'),kpi('نفاد النقد (متشائم)',ws.out?'الشهر '+ws.out:'لا ينفد',ws.out?'bad':'good'),kpi('التعادل التشغيلي (أساسي)',bs.be?'الشهر '+bs.be:'لا يتحقق',bs.be?'good':'bad'),kpi('تمويل مطلوب للأمان (متشائم)',f(need*1.2,0),need?'bad':'good')])
+'<h4>مقارنة السيناريوهات</h4>'+tbl(['السيناريو','نمو الإيراد','نفاد النقد','التعادل التشغيلي','أدنى رصيد','الرصيد عند نهاية الأفق'],rows)
+'<h4>المسار الشهري — السيناريو الأساسي</h4>'+tbl(['الشهر','الإيراد','صافي التدفق','الرصيد'],mt)
+rec([ws.out?'في السيناريو المتشائم ينفد النقد في الشهر '+ws.out+': ابدأ طلب التمويل قبل ذلك بـ 6 أشهر على الأقل (نحو الشهر '+mw+').':'لا ينفد النقد حتى في السيناريو المتشائم ضمن الأفق المحدد.',need?'التمويل الموصى به نحو '+f(need*1.2,0)+' (أدنى رصيد سالب + 20% هامش أمان).':'لا حاجة لتمويل إضافي وفق الافتراضات.',bs.be?'التعادل التشغيلي متوقع في الشهر '+bs.be+': ركّز على الوصول إليه أسرع بخفض الثابت أو رفع الهامش.':'لا يتحقق التعادل: الإيراد لا ينمو بسرعة كافية مقابل التكاليف، راجع الأسعار أو الثابت.','راجع الافتراضات شهريًا واستبدل التقدير بالفعلي.'])
+aiOut('أنت مستشار مالي. اقترح خطة لإطالة المدرج النقدي وبدائل تمويل بناءً على: '+JSON.stringify({cash:v.cash,rev:v.rev,fx:v.fx,vp:v.vp,baseOut:bs.out,worstOut:ws.out}))}''', True)

add('sku-true-profit', 'ecom', '🧮', 'ربحية المنتج الحقيقية في المتجر (رسوم + شحن + مرتجعات + إعلان)',
    'سعر البيع ناقص التكلفة لا يكفي. أدخل منتجاتك لتعرف الربح الصافي الفعلي لكل طلب بعد رسوم المنصة والدفع والشحن والمرتجعات والإعلان، ومن يستحق التوسع ومن يستنزفك.',
    [F('d', 'المنتجات (منتج | سعر | تكلفة | شحن | طلبات شهريًا | مرتجعات % | إعلان لكل طلب)', 'textarea',
       'حقيبة جلد | 249 | 110 | 22 | 300 | 8 | 35\nساعة ذكية | 199 | 120 | 15 | 450 | 12 | 40\nكفر جوال | 39 | 8 | 12 | 1200 | 3 | 9\nسماعة | 149 | 85 | 15 | 380 | 15 | 38\nمحفظة | 89 | 30 | 14 | 500 | 5 | 20', r=6),
     F('mf', 'عمولة المنصة/المتجر %', 'n', 5), F('pg', 'رسوم الدفع %', 'n', 2.5), F('pf', 'رسوم الدفع الثابتة للطلب', 'n', 1), F('rs', 'نسبة المرتجعات القابلة لإعادة البيع %', 'n', 70)],
    r'''function compute(v){''' + PD + r'''
const R=lines(v.d).map(x=>({n:x[0],p:num(x[1]),c:num(x[2]),s:num(x[3]),q:num(x[4]),r:num(x[5])/100,a:num(x[6])})).filter(x=>x.n&&x.p>0);
if(!R.length)return'<b>أدخل منتجًا واحدًا على الأقل.</b>';
const rs=v.rs/100;
R.forEach(x=>{x.fee=(1-x.r)*x.p*v.mf/100;x.pay=x.p*v.pg/100+v.pf;x.ship=x.s*(1+x.r);x.rl=x.r*x.c*(1-rs);x.gross=(1-x.r)*(x.p-x.c);x.net=x.gross-x.fee-x.pay-x.ship-x.rl-x.a;x.m=pct(x.net,x.p);x.mp=x.net*x.q;x.naive=x.p-x.c;x.be=x.net>0?0:Infinity});
const S=R.slice().sort((a,b)=>b.mp-a.mp),T=sum(R.map(x=>x.mp));
const rows=S.map(x=>[x.n,f(x.p,0),f(x.naive,0),f(x.fee+x.pay,1),f(x.ship,1),f(x.rl,1),f(x.a,0),'<b style="color:'+(x.net>=0?'#0a7':'#c33')+'">'+f(x.net,1)+'</b>',f(x.m,1)+'%',f(x.q,0),f(x.mp,0),x.net<0?'🔴 تخسر — عدّل السعر أو أوقف الإعلان':x.m<8?'🟠 هامش ضعيف':x.m>=20?'🟢 وسّع':'🔵 حافظ']);
const neg=R.filter(x=>x.net<0),worst=R.slice().sort((a,b)=>a.m-b.m)[0],best=S[0];
const bea=x=>{const unit=x.net+x.a;return unit>0?f(unit/Math.max(.01,x.a),1)+'x':'—'};
return kpis([kpi('صافي الربح الشهري',f(T,0),T>=0?'good':'bad'),kpi('منتجات خاسرة',neg.length,neg.length?'bad':'good'),kpi('الأربح شهريًا',best.n),kpi('الأضعف هامشًا',worst.n+' ('+f(worst.m,1)+'%)',worst.m<0?'bad':'')])
+'<h4>الربح الحقيقي لكل منتج</h4>'+tbl(['المنتج','السعر','هامش ساذج (سعر−تكلفة)','رسوم منصة+دفع','شحن (مع المرتجع)','خسارة المرتجع','إعلان/طلب','صافي الطلب','هامش صافٍ','طلبات','ربح شهري','القرار'],rows)
+rec([neg.length?'منتجات تخسر فعليًا: '+neg.map(x=>x.n).join('، ')+'. كل طلب يُباع منها يخفض أرباحك رغم أنه يبدو مربحًا.':'كل المنتجات رابحة بعد جميع التكاليف.','المرتجعات تضرب الهامش مرتين (شحن مرتد + سلعة غير قابلة للبيع): خفض المرتجعات من '+f(worst.r*100,0)+'% للمنتج الأضعف يحسن ربحيته بأسرع من خفض التكلفة.','حدّ الإعلان: لا تتجاوز الربح قبل الإعلان؛ مثلًا '+best.n+' يتحمل حتى '+f(best.net+best.a,0)+' إعلانًا للطلب قبل أن يصل لصفر.','اجمع المنتجات منخفضة السعر في باقات لرفع قيمة الطلب وتخفيف أثر الشحن والرسوم الثابتة.'])
+aiOut('أنت مستشار تجارة إلكترونية. اقترح خطة لتحسين ربحية المنتجات التالية (تسعير، باقات، إيقاف إعلان، تقليل مرتجعات): '+JSON.stringify(S.map(x=>({n:x.n,net:Math.round(x.net),m:Math.round(x.m),ret:x.r}))))}''', True)
